class Solution {
public:
    string multiply(string num1, string num2) {
        int n = num1.size(), m = num2.size();
        vector<int> cols(n + m, 0);
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                int sum = (num1[i] - '0') * (num2[j] - '0') + cols[i + j + 1];
                cols[i + j + 1] = sum % 10;
                cols[i + j] += sum / 10;
            }
        }
        string res;
        for (int d : cols) {
            if (!(res.empty() && d == 0)) res.push_back('0' + d);
        }
        return res.empty() ? "0" : res;
    }
};
